import React, { useState, useEffect } from 'react';
import axios from 'axios';
import PiePagina from '../Componentes/PiePagina';

function Inicio() {
  const [perrosAPI, setPerrosAPI] = useState([]);
  const [cargando, setCargando] = useState(true);

  const mensajes = [
    {
      titulo: 'Un amigo te espera',
      texto: 'El inicio de una gran historia juntos.'
    },
    {
      titulo: 'Huellas que sanan el alma',
      texto: 'Dale la oportunidad de cambiar tu vida.'
    },
    {
      titulo: 'Un hogar para mí, una alegría para ti',
      texto: 'Adopta con el corazón.'
    },
    {
      titulo: 'No busques amor, adóptalo',
      texto: 'Tu compañero ideal está listo para conocerte.'
    },
    {
      titulo: 'Amor incondicional en cuatro patas',
      texto: 'El amigo fiel que siempre soñaste.'
    },
    {
      titulo: 'Cambia su destino, comparte tu hogar',
      texto: 'Adopta responsabilidad y cariño.'
    }
  ];

  useEffect(() => {
    axios
      .get('https://dog.ceo/api/breeds/image/random/6')
      .then((respuesta) => {
        setPerrosAPI(respuesta.data.message);
        setCargando(false);
      })
      .catch((error) => {
        console.error('Error al consumir la API:', error);
        setCargando(false);
      });
  }, []);

  return (
    <>
      <main className="contenedor">

        <section className="bienvenida">
          <h2 className="titulo-seccion">
            Bienvenidos a Huellitas de Amor
          </h2>

          <p className="descripcion-seccion">
            Somos una organización dedicada al rescate,
            rehabilitación y adopción responsable de perros
            y gatos. ¡Encuentra a tu nuevo mejor amigo hoy!
          </p>
        </section>

        <section className="seccion-mascotas">

          <h3 className="titulo-mascotas">
            🐾 ¡Amigos que esperan una familia!
          </h3>

          <p className="subtitulo-mascotas">
            Cada huellita merece un hogar lleno de amor.
          </p>

          {cargando ? (
            <div className="cargando">
              Cargando fotografías de nuestros amigos...
            </div>
          ) : (
            <div className="grid-tarjetas">

              {perrosAPI.map((urlImagen, index) => (
                <div key={index} className="tarjeta">

                  <img
                    src={urlImagen}
                    alt={`Fotografía de una mascota ${index + 1}`}
                  />

                  <div className="tarjeta-contenido">

                    <h3>{mensajes[index].titulo}</h3>

                    <p>{mensajes[index].texto}</p>

                    <p>¿Me conoces?</p>

                    <a
                      href="/contacto"
                      className="boton-adoptar"
                    >
                      Conóceme ❤️
                    </a>

                  </div>
                </div>
              ))}

            </div>
          )}

        </section>

      </main>

      <PiePagina />
    </>
  );
}

export default Inicio;
